import { usePathname } from 'next/navigation';
import { Provider } from 'react-redux';
import store from './toolkit/store'; // adjust this path as needed
import Header from './components/Header';
import FooterComponents from './components/FooterComponents';
import { CartProvider } from "./cartcontext";


export default function RootLayout({ children }) {
  const pathname = usePathname();
  const isDashboard = pathname.startsWith('/admin') || pathname === '/login' || pathname === '/register' || pathname === '/order-success' ; // true if on /dashboard/* pages

  return (
    <html lang="en">
      <body className={isDashboard ? 'dashboard' : '' }  >
        <Provider store={store}>
         
          {!isDashboard && <Header id="main-header" /> }
          
          {/* {children} */}
           <CartProvider>{children}</CartProvider>

          {!isDashboard && <FooterComponents id="main-footer" />}
        </Provider>
      </body>
    </html>
  );
}

